-- ----- Bang writing_tests -----
DROP TABLE IF EXISTS `writing_tests`;
CREATE TABLE `writing_tests` (
  `id` varchar(36) NOT NULL,
  `title` text NOT NULL,
  `task` enum('task1','task2') NOT NULL,
  `prompt` text NOT NULL,
  `image_url` text,
  `time_minutes` int NOT NULL DEFAULT '40',
  `difficulty` enum('easy','medium','hard') NOT NULL DEFAULT 'medium',
  `is_published` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT (now()),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `writing_tests` VALUES ('0d303caf-26ea-438c-8d8a-e333c648d416','Water Consumption in Different Sectors (Task 1)','task1','The pie charts show the share of global water consumption among three sectors: agriculture, industry, and domestic use, in 1900 and 2000. Summarize the main features and make comparisons. Write at least 150 words.','https://images.unsplash.com/photo-1518173946687-a4c8a383392f?auto=format&fit=crop&w=800&q=80',20,'medium',1,'2026-06-25 08:12:46'),('5b06c64d-ff79-4e75-ba1d-a12239b7bcc1','Government Spending on Arts vs. Sciences (Task 2)','task2','Some people argue that governments should spend more money on funding scientific research rather than supporting the arts. Discuss both views and give your opinion. Write at least 250 words.',NULL,40,'hard',1,'2026-06-25 08:12:46'),('6b975562-fc39-4811-aa08-f660218a8f76','Working From Home vs. Office (Task 2)','task2','Nowadays, many employers allow their employees to work from home instead of coming to the office. Do the advantages of this trend outweigh the disadvantages? Support your opinion with reasons and examples. Write at least 250 words.',NULL,40,'medium',1,'2026-06-25 08:12:46'),('84eb38a9-14cd-43de-b546-bdc35f6f9d0c','Global Temperature Anomalies (Task 1)','task1','The table below shows global temperature changes relative to the historical average across five continents over three decades (1980s, 1990s, and 2000s). Summarize the information by selecting and reporting the main features. Write at least 150 words.','https://images.unsplash.com/photo-1451187580459-43490279c0fa?auto=format&fit=crop&w=800&q=80',20,'hard',1,'2026-06-25 08:12:46'),('b06804df-c226-419c-b865-6285b936efdd','NYC Airport Visitors 1995-2000 (Task 1)','task1','The chart below shows the number of travelers using three major airports in New York City (John F. Kennedy, LaGuardia, Newark) between 1995 and 2000. Summarize the information by selecting and reporting the main features, and make comparisons where relevant. Write at least 150 words.','https://images.unsplash.com/photo-1544016768-982d1554f0b9?auto=format&fit=crop&w=800&q=80',20,'easy',1,'2026-06-25 08:12:46'),('c74b1a8d-ea1a-4d89-801d-a6eb001ff7ae','Impact of Social Media on Teenagers (Task 2)','task2','Many people claim that social media platforms have a negative effect on teenagers\' social development and mental health. To what extent do you agree or disagree with this statement? Give specific reasons and examples to support your view. Write at least 250 words.',NULL,40,'medium',1,'2026-06-25 08:12:46'),('d7ec0c53-672f-4de1-b442-af5bce162f8c','Energy Consumption in the UK (Task 1)','task1','The graph below shows energy consumption by fuel type in the United Kingdom from 1981 to 2008. Summarize the information by selecting and reporting the main features, and make comparisons where relevant. Write at least 150 words.','https://images.unsplash.com/photo-1473341304170-971dccb5ac1e?auto=format&fit=crop&w=800&q=80',20,'medium',1,'2026-06-25 08:12:46'),('f8e2c5e8-db27-487e-92ff-26af3e5b8092','Should Higher Education be Free? (Task 2)','task2','Some people believe that university education should be free for everyone, regardless of their income level. Others argue that students should pay for their tuition fees as they are the ones who benefit from it. Discuss both views and give your opinion. Write at least 250 words.',NULL,40,'hard',1,'2026-06-25 08:12:46');

-- ----- Bang writing_submissions -----
DROP TABLE IF EXISTS `writing_submissions`;
CREATE TABLE `writing_submissions` (
  `id` varchar(36) NOT NULL,
  `user_id` varchar(36) NOT NULL,
  `test_id` varchar(36) NOT NULL,
  `essay` text NOT NULL,
  `word_count` int NOT NULL DEFAULT '0',
  `task_achievement` varchar(10) DEFAULT NULL,
  `coherence_cohesion` varchar(10) DEFAULT NULL,
  `lexical_resource` varchar(10) DEFAULT NULL,
  `grammatical_range` varchar(10) DEFAULT NULL,
  `overall_band` varchar(10) DEFAULT NULL,
  `feedback` text,
  `improved_essay` text,
  `time_taken` int DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT (now()),
  PRIMARY KEY (`id`),
  KEY `writing_submissions_user_id_users_id_fk` (`user_id`),
  KEY `writing_submissions_test_id_writing_tests_id_fk` (`test_id`),
  CONSTRAINT `writing_submissions_test_id_writing_tests_id_fk` FOREIGN KEY (`test_id`) REFERENCES `writing_tests` (`id`),
  CONSTRAINT `writing_submissions_user_id_users_id_fk` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----- Bang speaking_tests -----
DROP TABLE IF EXISTS `speaking_tests`;
CREATE TABLE `speaking_tests` (
  `id` varchar(36) NOT NULL,
  `title` text NOT NULL,
  `part` enum('part1','part2','part3') NOT NULL,
  `questions` json NOT NULL,
  `cue_card` text,
  `preparation_time` int DEFAULT '60',
  `speaking_time` int NOT NULL DEFAULT '120',
  `difficulty` enum('easy','medium','hard') NOT NULL DEFAULT 'medium',
  `is_published` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT (now()),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `speaking_tests` VALUES ('43709d25-9e98-4cfa-984a-39d4645cf835','Speaking Part 2: Describe a Person You Admire','part2','[]','Describe a person you admire or look up to.\n\nYou should say:\n- Who this person is\n- How you know them\n- What their character is like\n- And explain why you admire them so much.',60,120,'medium',1,'2026-06-25 08:12:46'),('53bb3853-9879-4417-8b4f-d7b3c8c8e06f','Speaking Part 1: Food and Dining Habits','part1','[\"What is your favorite food and why?\", \"Do you prefer cooking at home or eating out at restaurants?\", \"How has your diet changed since you were a child?\", \"Is fast food popular in your country?\"]',NULL,60,120,'easy',1,'2026-06-25 08:12:46'),('73f06ef2-f6d5-4c27-aa2a-8bd89213377a','Speaking Part 1: Technology and Apps','part1','[\"What is your favorite mobile application and how often do you use it?\", \"Has technology made your daily schedule easier or more complicated?\", \"Do you think kids spend too much time on smartphones nowadays?\"]',NULL,60,120,'easy',1,'2026-06-25 08:12:46'),('a3bbfce9-2b1b-4cb3-9bc1-cd0a1b11976c','Speaking Part 2: Describe a Useful Book','part2','[]','Describe a book you have read recently that you found useful.\n\nYou should say:\n- What the book is\n- Who wrote it\n- What it is about\n- And explain why you found it useful.',60,120,'medium',1,'2026-06-25 08:12:46'),('ad6f3b2a-ddbe-4aae-a0eb-d709b7a069e5','Speaking Part 1: Hometown and Hobbies','part1','[\"Let\'s talk about your hometown. Where is your hometown located?\", \"What do you like most about your hometown?\", \"Let\'s move on to talk about hobbies. What do you do in your free time?\", \"Do you prefer spending your free time alone or with friends?\"]',NULL,60,120,'easy',1,'2026-06-25 08:12:46'),('ae164ec1-cc80-468f-b1c9-b3f88f3526f6','Speaking Part 2: Describe a Memorable Journey','part2','[]','Describe a memorable journey you went on.\n\nYou should say:\n- Where you went\n- How you traveled there\n- Who you traveled with\n- And explain why this journey was so memorable to you.',60,120,'medium',1,'2026-06-25 08:12:46'),('da441700-0e63-4300-b12a-a7bb34deee16','Speaking Part 3: Tourism and Infrastructure','part3','[\"How does tourism affect local economies in developing nations?\", \"What can governments do to promote eco-friendly and sustainable tourism?\", \"Do you think international travel builds better relationships between countries?\"]',NULL,60,180,'hard',1,'2026-06-25 08:12:46'),('e12f9405-4073-41ed-bbfd-bca5d7526efc','Speaking Part 3: Reading Habits and Technology','part3','[\"Do you think paper books will be completely replaced by e-books in the future?\", \"What are the benefits of reading compared to watching videos for children?\", \"Should governments invest in public libraries in the digital era?\"]',NULL,60,180,'hard',1,'2026-06-25 08:12:46');

-- ----- Bang speaking_submissions -----
DROP TABLE IF EXISTS `speaking_submissions`;
CREATE TABLE `speaking_submissions` (
  `id` varchar(36) NOT NULL,
  `user_id` varchar(36) NOT NULL,
  `test_id` varchar(36) NOT NULL,
  `transcripts` json NOT NULL,
  `audio_urls` json DEFAULT NULL,
