  CONSTRAINT `speaking_submissions_test_id_speaking_tests_id_fk` FOREIGN KEY (`test_id`) REFERENCES `speaking_tests` (`id`),
  CONSTRAINT `speaking_submissions_user_id_users_id_fk` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----- Bang reading_passages -----
DROP TABLE IF EXISTS `reading_passages`;
CREATE TABLE `reading_passages` (
  `id` varchar(36) NOT NULL,
  `title` text NOT NULL,
  `passage` text NOT NULL,
  `difficulty` enum('easy','medium','hard') NOT NULL DEFAULT 'medium',
  `time_minutes` int NOT NULL DEFAULT '20',
  `is_published` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT (now()),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `reading_passages` VALUES ('07b02be8-6db6-43b9-bc71-f02c000d8325','The Rise of Urban Farming in Modern Cities','Urban farming, the practice of cultivating crops within city boundaries, has transitioned from a niche hobby to a critical urban planning tool. Modern vertical farms utilize hydroponic and aeroponic systems to grow vegetables in stacked layers, completely eliminating the need for soil. These indoor facilities control temperature, humidity, and light spectra to optimize crop yield and reduce growth cycles.\n\nBy locating agricultural production closer to metropolitan consumer hubs, vertical farms eliminate emissions and logistics costs associated with long-distance food transport. Furthermore, closed-loop hydroponic systems use up to 95% less water than traditional open-field farming. However, critics point out the high electricity demands of continuous artificial LED lighting, arguing that the system remains commercially viable only for high-value leafy greens.','medium',20,1,'2026-06-25 08:12:46'),('0becdcc1-55b4-4026-934f-aab599697a25','Architectural Evolution of the Italian Renaissance','Renaissance architecture, developing in Florence in the early 15th century, marked a conscious rejection of the complex, asymmetrical Gothic style. Led by figures like Filippo Brunelleschi and Leon Battista Alberti, architects sought inspiration in the symmetry, proportion, and geometry of classical Roman ruins. They revived the use of semicircular arches, hemispherical domes, and classical column arrangements.\n\nBrunelleschi\'s design for the dome of Florence Cathedral (Santa Maria del Fiore) represented a landmark engineering feat, constructing a massive double-walled octagonal dome without temporary wooden scaffolding. These designs emphasized human scale and rational layout, reflecting the broader intellectual shifts of Renaissance humanism which placed human reason and sensory experience at the center of cultural development.','medium',20,1,'2026-06-25 08:12:46'),('2bd3d8df-14b0-463b-87c8-59efb60a5cb4','Evolution and Social Impact of the Bicycle','The bicycle is one of the most efficient transport inventions in history. Its early ancestor, the \'dandy horse\' invented by Karl von Drais in 1817, lacked pedals and required riders to push off the ground with their feet. The mid-19th century introduced the \'boneshaker\' with pedals attached directly to the front wheel, followed by the high-wheeled penny-farthing. The penny-farthing\'s massive front wheel allowed higher speeds but was notoriously unstable and dangerous.\n\nBy the late 1880s, the safety bicycle emerged, featuring equal-sized wheels, a chain drive, and pneumatic rubber tires. This design democratized travel, offering affordable, independent mobility to working classes, particularly women. It played a major role in early women\'s suffrage movements by increasing their freedom of movement and prompting changes in restrictive Victorian clothing standards.','easy',15,1,'2026-06-25 08:12:46'),('5e151637-8614-4da3-b6bc-0ce61e00d948','Deep-Sea Hydrothermal Vent Ecosystems','Hydrothermal vents are fissures on the seafloor that release geothermally heated water rich in dissolved minerals. Located miles below the ocean surface where sunlight cannot penetrate, these vents support complex communities of life that do not rely on photosynthesis. Instead, these ecosystems are fueled by chemosynthesis, a process in which specialized bacteria convert toxic hydrogen sulfide gas from the vents into usable organic energy.\n\nThese bacteria form the base of a food chain that supports giant tubeworms, vent crabs, and pale shrimp. Tubeworms, which grow up to eight feet long, have no mouth or digestive tract, relying entirely on a symbiotic relationship with chemosynthetic bacteria housed inside their bodies. Discoveries at these vents have revolutionized biology, suggesting that life on Earth may have originated in deep-sea environments and raising possibilities for extraterrestrial life on icy moons.','hard',20,1,'2026-06-25 08:12:46'),('67725736-023b-40e3-8c33-1ae6c5df4e4d','The Threat of Climate Change to Forest Biodiversity','Forests are home to over 80% of the world\'s terrestrial biodiversity, hosting a vast array of plants, animals, and microorganisms. However, rapid changes in global temperatures and precipitation patterns are threatening these ecosystems. As temperatures rise, many species are forced to migrate towards higher altitudes or latitudes to find suitable habitats. For species with limited mobility, such as certain amphibians and flightless insects, these migration routes are often blocked by human infrastructure, leading to localized extinctions.\n\nIn addition to temperature shifts, climate change is altering the frequency and intensity of natural disturbances, such as forest fires and pest outbreaks. Warmer winters allow insect pests like bark beetles to survive and reproduce in greater numbers, causing widespread devastation to coniferous forests in North America. These dead trees then act as fuel for massive wildfires, which further degrade the habitat and release stored carbon dioxide into the atmosphere, accelerating the greenhouse effect.\n\nConservationists argue that protecting existing forest ecosystems is crucial, but not sufficient. Active forest management strategies, such as establishing wildlife corridors and assisting species migration, are becoming increasingly necessary to preserve global biodiversity. By creating continuous pathways of natural habitat, scientists hope to enable vulnerable species to adapt to the changing climate naturally.','medium',20,1,'2026-06-25 08:12:46'),('794e1c23-66d4-4d09-bb34-90237b1a36c5','William Henry Perkin and Synthetic Dyes','William Henry Perkin was a British chemist who is best known for his accidental discovery of the first synthetic dye, which he named \'mauveine\'. Born on March 12, 1838, in London, Perkin showed an early interest in science and began conducting chemistry experiments in his makeshift laboratory at home. At the age of 15, he entered the Royal College of Chemistry, where he studied under the renowned chemist August Wilhelm von Hofmann.\n\nIn 1856, while working on a project to synthesize quinine (a treatment for malaria), Perkin accidentally produced a dark purple residue. Curious about this unexpected result, he realized it could be used as a dye for fabrics. This discovery led to the creation of mauveine, which revolutionized the textile industry, making vibrant purple clothing affordable and accessible to the wider public.\n\nPerkin patented his discovery and established a factory to produce mauveine on a commercial scale. This laid the foundation for the modern chemical industry and proved that laboratory research could yield enormous commercial and practical applications.','medium',20,1,'2026-06-25 08:12:46'),('7cad4c30-ea1a-401f-8406-86e6445ca5ab','The History and Cultivation of Tea','Tea is the world\'s most consumed beverage after water, with its origins tracing back to ancient China. According to legend, Emperor Shen Nung discovered tea in 2737 BC when wild leaves drifted into his boiling water. Cultivation of the tea plant, Camellia sinensis, became widespread during the Tang Dynasty, developing into a complex cultural ritual. By the 17th century, tea reached Europe through Dutch merchants, where it quickly became a luxury item among the aristocracy.\n\nToday, tea is grown in tropical and subtropical regions worldwide, primarily in China, India, Kenya, and Sri Lanka. The characteristics of the tea are determined by the soil quality, altitude, and processing methods. Leaves are harvested by hand and undergo varying degrees of oxidation to produce white, green, oolong, or black tea. As awareness of its health benefits grows, international consumption continues to climb.','easy',15,1,'2026-06-25 08:12:46'),('d3472f3e-64ce-4713-9493-ea3e75554edb','Understanding Human Memory Consolidation','Memory consolidation is the neurological process by which temporary sensory impressions are transformed into stable, long-term memories. The hippocampus, located in the temporal lobe, acts as a temporary sorting center, registering new experiences. However, long-term retention requires these traces to be transferred to the neocortex, where they are integrated into existing cognitive frameworks.\n\nThis transfer primarily occurs during sleep, particularly slow-wave NREM sleep. Synaptic consolidation, happening within hours of learning, strengthens local neural paths, while systemic consolidation reorganizes brain networks over weeks or years. Interference during these critical periods—such as trauma, high stress, or sleep deprivation—can disrupt the consolidation process, leading to memory loss or distortion.','hard',20,1,'2026-06-25 08:12:46'),('d3afa8ca-2d59-4576-ad61-5e76d8e9a776','The Neurobiology of Human Sleep','Sleep is a vital physiological process characterized by altered consciousness and inhibited sensory activity. Modern sleep research identifies two primary categories: REM (Rapid Eye Movement) and NREM (Non-Rapid Eye Movement) sleep. NREM sleep is further divided into three distinct stages, spanning from light slumber to deep slow-wave sleep. During deep sleep, the body undergoes critical cellular repair and growth hormone release.\n\nREM sleep is the stage most closely associated with vivid dreaming. Brain activity during REM spikes to levels similar to waking hours, yet the body experience muscle paralysis to prevent the physical acting out of dreams. Disruptions in sleep cycles are linked to cognitive decline, metabolic disorders, and weakened immune responses. Understanding these neurological systems helps scientists develop therapies for chronic sleep disorders like insomnia and sleep apnea.','hard',20,1,'2026-06-25 08:12:46'),('f1db1631-63c6-4e4b-8c47-d757b1dad69f','Artificial Intelligence in Medical Diagnostic Systems','Deep learning models have shown remarkable accuracy in diagnostic medicine, occasionally matching or exceeding the performance of human radiologists. By training neural networks on millions of clinical images, AI systems learn to recognize subtle patterns of tumors, fractures, or retinal decay that might escape human eyes. These applications drastically reduce diagnostic time, allowing doctors to identify diseases at much earlier stages.\n\nDespite these benefits, the integration of AI diagnostics faces hurdles. One main issue is the \'black box\' problem, where deep learning algorithms generate correct outcomes but cannot explain their mathematical reasoning. This lack of transparency raises ethical and legal questions regarding accountability if a misdiagnosis occurs. Consequently, experts recommend using AI as a supportive decision-making tool rather than an autonomous diagnostic authority.','medium',20,1,'2026-06-25 08:12:46');

-- ----- Bang reading_questions -----
DROP TABLE IF EXISTS `reading_questions`;
CREATE TABLE `reading_questions` (
  `id` varchar(36) NOT NULL,
  `passage_id` varchar(36) NOT NULL,
  `type` enum('multiple_choice','multiple_answers','short_answer','true_false_not_given','matching','fill_blank') NOT NULL,
  `question` text NOT NULL,
  `options` json DEFAULT NULL,
  `correct_answer` json NOT NULL,
  `explanation` text,
  `order_index` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `reading_questions_passage_id_reading_passages_id_fk` (`passage_id`),
  CONSTRAINT `reading_questions_passage_id_reading_passages_id_fk` FOREIGN KEY (`passage_id`) REFERENCES `reading_passages` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `reading_questions` VALUES ('1199b5ef-2d7c-45fd-bdd6-9e3932a02947','2bd3d8df-14b0-463b-87c8-59efb60a5cb4','true_false_not_given','Penny-farthing bicycles were popular because they were extremely safe.',NULL,'\"FALSE\"','The passage states the penny-farthing \'was notoriously unstable and dangerous.\'',1),('1445b4e9-b9bf-40bf-bd9c-1c3393068013','2bd3d8df-14b0-463b-87c8-59efb60a5cb4','multiple_choice','What did the earliest ancestor of the bicycle (dandy horse) lack?','[\"A. Pedals\", \"B. Wheels\", \"C. Handlebars\", \"D. Seats\"]','\"A\"','The passage states the dandy horse \'lacked pedals and required riders to push off the ground.\'',0),('14e8c0e7-4f7e-4664-af2f-ed64a638f390','0becdcc1-55b4-4026-934f-aab599697a25','fill_blank','Renaissance design principles reflected the cultural shift toward Renaissance _________.',NULL,'\"humanism\"','The passage states: \'reflecting the broader intellectual shifts of Renaissance humanism...\'',2),('21c3f9b1-37c7-4eb7-8111-c4283a6f92f3','d3afa8ca-2d59-4576-ad61-5e76d8e9a776','true_false_not_given','Cellular repair mostly occurs during REM sleep.',NULL,'\"FALSE\"','The passage states: \'During deep sleep [NREM], the body undergoes critical cellular repair.\'',0),('27f580f5-282f-418a-b35d-405a6ec63618','5e151637-8614-4da3-b6bc-0ce61e00d948','true_false_not_given','Giant tubeworms digest their food using a well-developed stomach and digestive tract.',NULL,'\"FALSE\"','The passage states: \'Tubeworms... have no mouth or digestive tract, relying entirely on a symbiotic relationship...\'',1),('2a3a2cfc-e874-4672-9bf9-7874293b78a2','67725736-023b-40e3-8c33-1ae6c5df4e4d','true_false_not_given','Bark beetles reproduction rate decreases during warmer winters.',NULL,'\"FALSE\"','Paragraph 2 states: \'Warmer winters allow insect pests like bark beetles to survive and reproduce in greater numbers.\'',1),('315c9058-0f9e-49c1-be65-0f464c00b7fe','07b02be8-6db6-43b9-bc71-f02c000d8325','true_false_not_given','Vertical farms require large volumes of organic soil to function.',NULL,'\"FALSE\"','The passage states vertical farms \'utilize hydroponic and aeroponic systems... completely eliminating the need for soil.\'',0),('3c980bc8-37de-409a-b252-de099436c950','7cad4c30-ea1a-401f-8406-86e6445ca5ab','multiple_choice','According to Chinese legend, who discovered tea?','[\"A. An unknown Tang Dynasty farmer\", \"B. Emperor Shen Nung\", \"C. Dutch merchants\", \"D. An aristocratic family\"]','\"B\"','The passage states: \'According to legend, Emperor Shen Nung discovered tea in 2737 BC.\'',0),('45a77e5b-afb9-4089-aa07-fff84ebfb075','d3472f3e-64ce-4713-9493-ea3e75554edb','true_false_not_given','Systemic memory consolidation occurs over a matter of hours.',NULL,'\"FALSE\"','The passage states systemic consolidation reorganizes brain networks \'over weeks or years.\'',1),('54c34487-6fdd-4acc-bac8-7923dc23b698','d3472f3e-64ce-4713-9493-ea3e75554edb','fill_blank','New sensory impressions are temporarily registered in the _________.',NULL,'\"hippocampus\"','The passage states: \'The hippocampus... acts as a temporary sorting center, registering new experiences.\'',0),('5a978517-da3a-428b-bdc9-57b4ec9768ed','5e151637-8614-4da3-b6bc-0ce61e00d948','fill_blank','Chemosynthetic bacteria convert toxic _________ sulfide gas into usable energy.',NULL,'\"hydrogen\"','The passage states: \'bacteria convert toxic hydrogen sulfide gas from the vents...\'',2),('5d7442da-cabb-4af1-9bc2-d7f826e2df5e','794e1c23-66d4-4d09-bb34-90237b1a36c5','true_false_not_given','William Henry Perkin received formal education in Germany.',NULL,'\"FALSE\"','The passage mentions he studied at the Royal College of Chemistry, which is in London, under August Wilhelm von Hofmann.',2),('60e575fc-fc5e-46b3-b309-e3428cd339fa','5e151637-8614-4da3-b6bc-0ce61e00d948','multiple_choice','What chemical process replaces photosynthesis in hydrothermal vent ecosystems?','[\"A. Photosynthesis\", \"B. Chemosynthesis\", \"C. Hydrothermal synthesis\", \"D. Organic decay\"]','\"B\"','The passage states: \'Instead, these ecosystems are fueled by chemosynthesis...\'',0),('63d78fe9-6762-4504-86f5-fac4d2ca71ff','d3afa8ca-2d59-4576-ad61-5e76d8e9a776','multiple_choice','Why doesn\'t the human body move or act out dreams during REM sleep?','[\"A. The eyes move too rapidly.\", \"B. The brain experiences a complete lack of activity.\", \"C. The body undergoes temporary muscle paralysis.\", \"D. Hormones prevent any muscle contractions.\"]','\"C\"','The passage states: \'yet the body experience muscle paralysis to prevent the physical acting out of dreams.\'',2),('653f222e-d914-4af7-8c8b-8b9735da5c3e','794e1c23-66d4-4d09-bb34-90237b1a36c5','fill_blank','The accidental synthetic dye discovered by Perkin was named _________.',NULL,'\"mauveine\"','Paragraph 1 and 2 mention he named it \'mauveine\'.',4),('76141cf4-8d98-4a64-941e-d8a732ab3afb','d3afa8ca-2d59-4576-ad61-5e76d8e9a776','fill_blank','The sleep stage associated with dreaming is called _________ sleep.',NULL,'\"REM\"','The passage states: \'REM sleep is the stage most closely associated with vivid dreaming.\'',1),('7737caf9-f5dd-4edb-af77-dc04b28cea5e','7cad4c30-ea1a-401f-8406-86e6445ca5ab','fill_blank','The tea plant is scientifically known as Camellia _________.',NULL,'\"sinensis\"','The passage states: \'Cultivation of the tea plant, Camellia sinensis...\'',1),('9107e8f1-6df5-465c-9e7d-ae51b8407441','f1db1631-63c6-4e4b-8c47-d757b1dad69f','fill_blank','The legal and ethical dilemma caused by AI\'s unexplained calculations is known as the _________ box problem.',NULL,'\"black\"','The passage refers to this as the \'black box\' problem.',1),('910f515f-242e-4323-8149-4b3d4b8e57f2','07b02be8-6db6-43b9-bc71-f02c000d8325','fill_blank','Vertical farms eliminate emissions by producing food closer to urban _________ hubs.',NULL,'\"consumer\"','The passage states: \'By locating agricultural production closer to metropolitan consumer hubs...\'',1),('935816ca-d947-4d73-a46b-132ab3963a64','f1db1631-63c6-4e4b-8c47-d757b1dad69f','multiple_choice','How do medical experts suggest that AI diagnostic tools be used in clinics?','[\"A. As completely autonomous medical directors\", \"B. To completely replace human radiologists\", \"C. As supportive decision-making aids\", \"D. Only for administrative filing work\"]','\"C\"','The passage states: \'experts recommend using AI as a supportive decision-making tool rather than an autonomous diagnostic authority.\'',2),('95713524-667d-4d0e-a65a-e08c41924dde','0becdcc1-55b4-4026-934f-aab599697a25','true_false_not_given','Filippo Brunelleschi used massive wooden scaffolding to build Florence Cathedral\'s dome.',NULL,'\"FALSE\"','The passage states Brunelleschi constructed the dome \'without temporary wooden scaffolding.\'',1),('a34cebb6-4a52-42dd-a0d3-4ee06a82ca24','2bd3d8df-14b0-463b-87c8-59efb60a5cb4','fill_blank','The bicycle design with equal-sized wheels developed in late 1880s was the _________ bicycle.',NULL,'\"safety\"','The passage states: \'By the late 1880s, the safety bicycle emerged.\'',2),('af73b736-8025-4f1e-95ed-e6e1f6f90574','f1db1631-63c6-4e4b-8c47-d757b1dad69f','true_false_not_given','AI medical tools consistently diagnose diseases slower than human radiologists.',NULL,'\"FALSE\"','The passage states: \'These applications drastically reduce diagnostic time.\'',0),('b476a75d-931d-4ac8-b7aa-ba10a05ed988','794e1c23-66d4-4d09-bb34-90237b1a36c5','multiple_choice','What was Perkin trying to synthesize when he accidentally discovered mauveine?','[\"A. Quinine for malaria treatment\", \"B. Synthetic dyes for silk fabric\", \"C. Pure carbon compounds\", \"D. Coal tar solutions\"]','\"A\"','The passage states: \'while working on a project to synthesize quinine (a treatment for malaria)...\'',3),('bd00c5bb-9ff0-4f59-a5fd-f69709d5311a','794e1c23-66d4-4d09-bb34-90237b1a36c5','true_false_not_given','Perkin entered the Royal College of Chemistry at the age of 15.',NULL,'\"TRUE\"','The passage states: \'At the age of 15, he entered the Royal College of Chemistry.\'',0),('ce1150c0-4be9-45ee-9952-f440f8bcf7a0','67725736-023b-40e3-8c33-1ae6c5df4e4d','multiple_choice','According to the first paragraph, what is the main reason some forest species face localized extinction?','[\"A. They are hunted by human populations.\", \"B. They cannot adapt to altitude changes.\", \"C. Human infrastructure prevents their migration to suitable habitats.\", \"D. Forest fires destroy their food sources.\"]','\"C\"','Paragraph 1 mentions: \'For species with limited mobility... migration routes are often blocked by human infrastructure, leading to localized extinctions.\'',0),('ce3ca173-1848-4606-9301-42aeeef2010b','0becdcc1-55b4-4026-934f-aab599697a25','multiple_choice','Which architectural elements were revived during the Italian Renaissance?','[\"A. Pointed arches and flying buttresses\", \"B. Semicircular arches and hemispherical domes\", \"C. Asymmetrical layouts and organic towers\", \"D. Modern glass walls and iron pillars\"]','\"B\"','The passage states: \'They revived the use of semicircular arches, hemispherical domes, and classical column arrangements.\'',0),('ce9af21b-e59e-4575-bdfe-103fe79266d6','794e1c23-66d4-4d09-bb34-90237b1a36c5','true_false_not_given','The passage states that Perkin’s discovery of mauveine made natural dyes more expensive.',NULL,'\"FALSE\"','The passage says mauveine made clothing affordable and accessible, and does not state it made natural dyes more expensive.',1),('d62a083b-6759-44d5-be80-67b1a446ad7c','07b02be8-6db6-43b9-bc71-f02c000d8325','multiple_choice','What is the primary criticism leveled against indoor vertical farming?','[\"A. Massive water waste\", \"B. High electricity demand of LED lighting\", \"C. Slower growth cycles\", \"D. High shipping and logistics fees\"]','\"B\"','The passage states: \'critics point out the high electricity demands of continuous artificial LED lighting...\'',2),('e15a3928-1c1b-480f-a0f1-425ecd925aa7','67725736-023b-40e3-8c33-1ae6c5df4e4d','fill_blank','To help vulnerable species adapt, scientists recommend establishing ___________ corridors.',NULL,'\"wildlife\"','Paragraph 3 mentions: \'Active forest management strategies, such as establishing wildlife corridors...\'',2),('e4658400-e106-40e3-8331-fd947be9d16b','7cad4c30-ea1a-401f-8406-86e6445ca5ab','true_false_not_given','Tea was introduced to Europe by British merchants in the 17th century.',NULL,'\"FALSE\"','The passage states tea reached Europe through \'Dutch merchants\', not British.',2),('f7a3c291-7534-4ba6-bd0c-523945af92e1','d3472f3e-64ce-4713-9493-ea3e75554edb','multiple_choice','Under what state does system-level memory transfer primarily happen?','[\"A. Active studying\", \"B. Deep NREM sleep\", \"C. High-stress environments\", \"D. Light REM sleep\"]','\"B\"','The passage states: \'This transfer primarily occurs during sleep, particularly slow-wave NREM sleep.\'',2);

-- ----- Bang reading_submissions -----
DROP TABLE IF EXISTS `reading_submissions`;
CREATE TABLE `reading_submissions` (
  `id` varchar(36) NOT NULL,
  `user_id` varchar(36) NOT NULL,
  `passage_id` varchar(36) NOT NULL,
  `answers` json NOT NULL,
  `score` int NOT NULL DEFAULT '0',
  `total_questions` int NOT NULL,
  `time_taken` int DEFAULT NULL,
  `feedback` text,
  `created_at` timestamp NOT NULL DEFAULT (now()),
  PRIMARY KEY (`id`),
  KEY `reading_submissions_user_id_users_id_fk` (`user_id`),
  KEY `reading_submissions_passage_id_reading_passages_id_fk` (`passage_id`),
  CONSTRAINT `reading_submissions_passage_id_reading_passages_id_fk` FOREIGN KEY (`passage_id`) REFERENCES `reading_passages` (`id`),
  CONSTRAINT `reading_submissions_user_id_users_id_fk` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----- Bang listening_tests -----
DROP TABLE IF EXISTS `listening_tests`;
CREATE TABLE `listening_tests` (
  `id` varchar(36) NOT NULL,
  `title` text NOT NULL,
  `audio_url` text NOT NULL,
  `transcript` text NOT NULL,
  `difficulty` enum('easy','medium','hard') NOT NULL DEFAULT 'medium',
  `time_minutes` int NOT NULL DEFAULT '30',
  `is_published` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT (now()),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `listening_tests` VALUES ('223a27e7-6fee-4ff9-b51f-4b1edc5193ed','Car Rental Inquiry Dialogue','https://www.soundhelix.com/examples/mp3/SoundHelix-Song-5.mp3','Agent: Hello! Welcome to Swift Car Rentals. What type of vehicle are you looking for?\nCustomer: Hi. I need a compact car for a weekend trip. Just for myself and my husband.\nAgent: We have a hybrid sedan available for 45 dollars a day, or a standard hatchback for 35 dollars a day.\nCustomer: We\'ll go with the hybrid sedan. We want to save on gas.\nAgent: Excellent. Will you need GPS navigation or an additional driver insurance policy?\nCustomer: Yes, we would like GPS navigation added. My husband will do all the driving, so no extra insurance is needed.\nAgent: Great, let\'s process your credit card.','medium',10,1,'2026-06-25 08:12:46'),('3148c458-d456-4562-900d-e36cbd60f88f','Travel Agency Booking Details','https://www.soundhelix.com/examples/mp3/SoundHelix-Song-6.mp3','Agent: Global Travels, good afternoon. How can I help you?\nTraveler: Hello, I\'d like to book a flight to Tokyo for next month, leaving on the 12th.\nAgent: Let me check. We have a direct flight leaving at 8:30 AM with Nippon Airways, or a one-stop flight leaving at 11:00 AM with Pacific Airlines.\nTraveler: I prefer the direct flight. What is the baggage allowance?\nAgent: You are allowed one carry-on bag up to 7 kg, and two checked bags up to 23 kg each.\nTraveler: That\'s perfect. Please book that flight for me.','easy',10,1,'2026-06-25 08:12:46'),('6a3f0011-bf67-4a11-92c0-65e7a21f29e4','Academic Lecture: The Roman Road Network','https://www.soundhelix.com/examples/mp3/SoundHelix-Song-7.mp3','Professor: Today, we look at the engineering of Roman roads. The Romans constructed over 400,000 kilometers of roads to connect their vast empire. These roads were primarily built for the rapid movement of armies and military supplies. They were constructed in straight lines, bypassing natural obstacles with tunnels or bridges. The foundations were made of gravel and clay, covered by large, flat stone blocks. This layout allowed rainwater to drain off, keeping roads usable in all weather conditions.','hard',15,1,'2026-06-25 08:12:46'),('6a6c361a-e4cd-41a9-a454-36c7709c7545','Library Membership Registration','https://www.soundhelix.com/examples/mp3/SoundHelix-Song-4.mp3','Librarian: Hello, how can I help you today?\nPatron: Hi, I\'d like to sign up for a library card, please.\nLibrarian: Sure, I can help you with that. Are you a local resident?\nPatron: Yes, I moved to Greenview last month. My address is 14 Maple Street.\nLibrarian: Great. I\'ll need to see some proof of address. A utility bill or driver\'s license will do.\nPatron: Here is my water bill.\nLibrarian: Perfect. There is no charge for local residents. The library card is free and allows you to borrow up to 10 books at a time. The loan period is 3 weeks.','easy',8,1,'2026-06-25 08:12:46'),('9848fadd-5aac-4696-b4ed-874232c12215','L01. Hotel Room Service Inquiry','https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3','Receptionist (Tess): Good evening! Room service. Tess speaking. How may I assist you?\nGuest (James): Hi Tess. I\'d like to order some dinner to my room, please.\nReceptionist: Certainly, sir. What would you like to have?\nGuest: I would like a grilled chicken sandwich, some French fries, and a small side salad with ranch dressing on the side.\nReceptionist: Got that. Would you like anything to drink?\nGuest: Yes, a large glass of fresh orange juice, please.\nReceptionist: Perfect. What is your room number, sir?\nGuest: I am in room 640.\nReceptionist: Thank you, Mr. James. Your order will be delivered in about twenty minutes.','easy',10,1,'2026-06-25 08:12:46'),('a56c6c55-666f-462d-94f0-b52276d26a96','Student Accommodation Request Form','https://www.soundhelix.com/examples/mp3/SoundHelix-Song-8.mp3','Officer: Good morning. Have you filled out the student housing application?\nStudent: Not yet. I had some questions about the room options. Is the single studio room still available?\nOfficer: Yes, we have studios in East Hall for 180 dollars a week, or shared double rooms in West Hall for 120 dollars a week. Utilities and high-speed internet are included in both rates.\nStudent: I prefer East Hall because I need a quiet space to study. Does it include parking?\nOfficer: Parking is an additional 25 dollars per month. You need to register your vehicle at the main office.','easy',10,1,'2026-06-25 08:12:46'),('b5b16319-8d84-4ddf-892b-51a444dd9678','Job Interview Scheduling','https://www.soundhelix.com/examples/mp3/SoundHelix-Song-3.mp3','HR Manager: Hello, is this Mark?\nCandidate: Yes, speaking. Good afternoon.\nHR Manager: Good afternoon Mark. I\'m calling from Zenith Consulting regarding your application for the Junior Web Developer position. We would like to invite you for an interview.\nCandidate: That\'s wonderful! Thank you.\nHR Manager: We have openings next Tuesday at 10 AM, or Wednesday at 2 PM. Which suits you?\nCandidate: Wednesday at 2 PM would be perfect, as I have another commitment on Tuesday morning.\nHR Manager: Excellent. We are located on the 4th floor of the Tower Plaza, Room 402. Please bring a printed copy of your resume.\nCandidate: Understood. See you on Wednesday.','medium',12,1,'2026-06-25 08:12:46'),('dc869b82-ecae-4cb3-9dcf-b2e63d5f2a93','Tutoring Session: Essay Structure Feedback','https://www.soundhelix.com/examples/mp3/SoundHelix-Song-10.mp3','Tutor: Hi Sarah, let\'s look at your essay draft. Your arguments on environmental policy are solid, but you need to restructure your body paragraphs. Each paragraph must start with a clear topic sentence.\nStudent: Okay. Should I add more data to support my points?\nTutor: Yes, especially in paragraph three. You should reference the 2018 United Nations climate report. Also, ensure your conclusion summarizes your main points rather than introducing new concepts.','hard',15,1,'2026-06-25 08:12:46'),('e9caa07f-864a-4340-bb49-2c47f9099e7b','Museum Tour Guide Dialogue','https://www.soundhelix.com/examples/mp3/SoundHelix-Song-9.mp3','Guide: Welcome to the Science Museum. Before we start our tour, please note that flash photography is strictly prohibited inside the main halls to protect historical manuscripts. The museum has three floors. The Ground floor hosts the Space exhibit, the first floor is dedicated to the History of Computers, and the top floor features Robotics. The cafe is located next to the main entrance on the ground floor.','medium',12,1,'2026-06-25 08:12:46'),('fcd00a8f-0fe1-4654-b405-6493f0998335','English Course Enrollment Inquiry','https://www.soundhelix.com/examples/mp3/SoundHelix-Song-2.mp3','Receptionist: Good morning! Welcome to the Royal Language School. How can I help you today?\nStudent: Good morning. I\'d like to ask for some information about your general English courses. I want to study for 4 weeks.\nReceptionist: Excellent. We have intensive classes that run from 9 AM to 1 PM daily, or part-time options. Our next course starts on Monday, the 5th of July.\nStudent: Great, Monday suits me. How much is the tuition fee for 4 weeks?\nReceptionist: The fee is 320 pounds including course materials. We also offer accommodation in local home-stays for an additional 150 pounds per week.\nStudent: I think I\'ll arrange my own accommodation. I\'d like to pay the tuition fee now, please.','easy',10,1,'2026-06-25 08:12:46');

-- ----- Bang listening_questions -----
DROP TABLE IF EXISTS `listening_questions`;
CREATE TABLE `listening_questions` (
  `id` varchar(36) NOT NULL,
  `test_id` varchar(36) NOT NULL,
  `type` enum('multiple_choice','multiple_answers','short_answer','true_false_not_given','matching','fill_blank') NOT NULL,
  `question` text NOT NULL,
  `options` json DEFAULT NULL,
  `correct_answer` json NOT NULL,
  `order_index` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `listening_questions_test_id_listening_tests_id_fk` (`test_id`),
  CONSTRAINT `listening_questions_test_id_listening_tests_id_fk` FOREIGN KEY (`test_id`) REFERENCES `listening_tests` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `listening_questions` VALUES ('00ca72a8-b0b2-4c7a-8228-f78f3bb3a67c','e9caa07f-864a-4340-bb49-2c47f9099e7b','fill_blank','The exhibit on Computer History is located on the _________ floor.',NULL,'\"first\"',1),('036ecf8c-ec8d-4f54-9fb7-1896af1c624f','9848fadd-5aac-4696-b4ed-874232c12215','multiple_choice','Who is speaking at the front desk?','[\"A. Tess\", \"B. James\", \"C. Anna\"]','\"A\"',0),('1792dcf6-7a0a-4187-95c9-048c6de2b545','b5b16319-8d84-4ddf-892b-51a444dd9678','fill_blank','The interview is scheduled on Wednesday at _________ PM.',NULL,'\"2\"',1),('22171b43-3658-4c59-b849-adc659a0c89b','3148c458-d456-4562-900d-e36cbd60f88f','multiple_choice','Which airline does the traveler book with?','[\"A. Nippon Airways\", \"B. Pacific Airlines\", \"C. Global Travels\", \"D. Tokyo Express\"]','\"A\"',0),('4d1c7aae-b510-445d-9ca2-7a76b330d315','9848fadd-5aac-4696-b4ed-874232c12215','multiple_choice','What room number is James in?','[\"A. 640\", \"B. 450\", \"C. 604\"]','\"A\"',2),('510c12fa-406a-4e82-b732-67e3a385355a','6a6c361a-e4cd-41a9-a454-36c7709c7545','fill_blank','The patron\'s address is 14 _________ Street.',NULL,'\"Maple\"',0),('54d55b8d-d531-4bf8-98fb-274ef7f7e648','dc869b82-ecae-4cb3-9dcf-b2e63d5f2a93','multiple_choice','What report should Sarah cite in paragraph three?','[\"A. 2018 United Nations climate report\", \"B. 2020 Global energy index\", \"C. 2015 Environmental protection analysis\", \"D. 2019 Green ecology paper\"]','\"A\"',0),('704bf51d-c83d-402b-834e-685315608cab','fcd00a8f-0fe1-4654-b405-6493f0998335','fill_blank','The total fee for the 4-week general English course is ___________ pounds.',NULL,'\"320\"',1),('7447b4e5-3199-41f5-bc90-86d38ead373a','e9caa07f-864a-4340-bb49-2c47f9099e7b','multiple_choice','What activity is strictly prohibited inside the museum?','[\"A. Taking notes\", \"B. Flash photography\", \"C. Wearing bags\", \"D. Speaking loudly\"]','\"B\"',0),('7a06f9e9-bdb6-438c-af4c-3c207647078a','223a27e7-6fee-4ff9-b51f-4b1edc5193ed','fill_blank','The hybrid sedan rental costs _________ dollars per day.',NULL,'\"45\"',1),('8613c1c6-bf0a-4d22-aa46-fa548e22d369','6a6c361a-e4cd-41a9-a454-36c7709c7545','multiple_choice','What is the maximum number of books a patron can borrow?','[\"A. 5 books\", \"B. 10 books\", \"C. 15 books\", \"D. 20 books\"]','\"B\"',1),('8806eb94-1471-450f-883c-3a17c10d5098','3148c458-d456-4562-900d-e36cbd60f88f','fill_blank','The checked baggage allowance is _________ kg per bag.',NULL,'\"23\"',1),('8f25e5f4-e6eb-4677-b448-23ee57a271c9','b5b16319-8d84-4ddf-892b-51a444dd9678','multiple_choice','What job position did Mark apply for?','[\"A. Senior Software Engineer\", \"B. Junior Web Developer\", \"C. Project Manager\", \"D. Human Resources Director\"]','\"B\"',0),('91d37a73-1031-422d-a503-c61246c1f491','9848fadd-5aac-4696-b4ed-874232c12215','multiple_choice','What kind of dressing does the man want with his salad?','[\"A. Ranch\", \"B. Italian\", \"C. Balsamic\"]','\"A\"',1),('9354d7ac-e790-4fc6-a85a-5529c0d0a1f1','a56c6c55-666f-462d-94f0-b52276d26a96','multiple_choice','Where is the single studio room located?','[\"A. West Hall\", \"B. East Hall\", \"C. South Square\", \"D. North Plaza\"]','\"B\"',0),('94d10363-79e0-4f5b-b995-2eaf0e8a2838','6a3f0011-bf67-4a11-92c0-65e7a21f29e4','multiple_choice','What was the primary purpose of the Roman roads?','[\"A. Expanding civilian postal services\", \"B. Rapid movement of military troops and gear\", \"C. Enhancing trade with nearby countries\", \"D. Promoting travel of architects\"]','\"B\"',1),('96076bec-4765-47db-864e-75d78ef8b70c','9848fadd-5aac-4696-b4ed-874232c12215','fill_blank','The guest wants a large glass of fresh _________ juice.',NULL,'\"orange\"',4),('b5e8b89d-0d4e-4909-b2c6-ccffc7ce46e4','dc869b82-ecae-4cb3-9dcf-b2e63d5f2a93','fill_blank','The tutor advises that the conclusion should _________ the main ideas.',NULL,'\"summarize\"',1),('b6fdf7e8-c30a-47b5-b1f7-8e2e55107011','a56c6c55-666f-462d-94f0-b52276d26a96','fill_blank','Parking registration costs an additional _________ dollars per month.',NULL,'\"25\"',1),('b8f06cad-27b2-4dff-9147-fe1ea487231c','9848fadd-5aac-4696-b4ed-874232c12215','fill_blank','The guest ordered a side salad with dressing on the _________.',NULL,'\"side\"',3),('c251e5f3-219d-4a4d-b773-05c84ac21e67','fcd00a8f-0fe1-4654-b405-6493f0998335','multiple_choice','When does the student\'s next English course start?','[\"A. Next Friday\", \"B. Monday, 5th of July\", \"C. Monday, 15th of July\", \"D. Next month\"]','\"B\"',0),('c51ba720-1d67-4b89-af7b-9c15e88d8306','223a27e7-6fee-4ff9-b51f-4b1edc5193ed','multiple_choice','Which vehicle did the customer choose to rent?','[\"A. Compact hatchback\", \"B. Hybrid sedan\", \"C. Full-size SUV\", \"D. Minivan\"]','\"B\"',0),('e1a0d912-cd6a-4a99-9718-c711fc55955e','6a3f0011-bf67-4a11-92c0-65e7a21f29e4','fill_blank','Romans constructed over _________ kilometers of road networks.',NULL,'\"400000\"',0);

-- ----- Bang listening_submissions -----
DROP TABLE IF EXISTS `listening_submissions`;
CREATE TABLE `listening_submissions` (
  `id` varchar(36) NOT NULL,
  `user_id` varchar(36) NOT NULL,
  `test_id` varchar(36) NOT NULL,
  `answers` json NOT NULL,
  `score` int NOT NULL DEFAULT '0',
  `total_questions` int NOT NULL,
  `time_taken` int DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT (now()),
  PRIMARY KEY (`id`),
  KEY `listening_submissions_user_id_users_id_fk` (`user_id`),
  KEY `listening_submissions_test_id_listening_tests_id_fk` (`test_id`),
  CONSTRAINT `listening_submissions_test_id_listening_tests_id_fk` FOREIGN KEY (`test_id`) REFERENCES `listening_tests` (`id`),
  CONSTRAINT `listening_submissions_user_id_users_id_fk` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;
